INSERT INTO `itinerary_days` VALUES ('0ca2a869-762c-49b0-b784-74e88a74a48b','2026-11-03 13:35:59.821','2026-11-03 13:35:59.821','4fdf289d-42e5-47f5-9228-00417e3ccdf5',2,'Khám phá Nam đảo','Tham quan các điểm đến Nam đảo, thưởng thức hải sản và dành thời gian ngắm hoàng hôn.','Sáng, Trưa, Tối'),('16342b0b-56e3-4144-bd2b-4be6de2960a0','2026-11-17 11:19:04.127','2026-11-17 11:19:04.127','ae2aece0-5df9-4e60-beab-d96cb4062c39',2,'Động Phong Nha – Động Thiên Đường','Đi thuyền vào động Phong Nha, tham quan động Thiên Đường theo lịch trình của đoàn.','Sáng, Trưa, Tối'),('1adda353-0d59-4754-bbbd-74b04d3828e8','2026-11-17 11:19:04.104','2026-11-17 11:19:04.104','8b0b6e6b-6ed9-43e7-91f2-637233dde14d',3,'Mã Pí Lèng – Sông Nho Quế','Chinh phục đèo Mã Pí Lèng, đi thuyền trên sông Nho Quế theo điều kiện thời tiết. Nghỉ đêm tại Mèo Vạc.','Sáng, Trưa, Tối'),('1cb72670-06ed-4c12-a8d3-0de53dd0463f','2026-11-17 11:19:04.030','2026-11-17 11:19:04.030','2cd9d21e-26f1-42d4-8a7d-1df5d2bf517a',3,'Tháp Bà Ponagar – Tạm biệt Nha Trang','Tham quan Tháp Bà Ponagar, mua sắm đặc sản, trả phòng và trở về TP. Hồ Chí Minh.','Sáng, Trưa'),('1d5004dd-34fc-4f14-8c31-f3f6db69a2af','2026-11-03 13:35:59.831','2026-11-03 13:35:59.831','eb9b1c60-dac3-41dc-9a89-8bc28bfa818d',2,'Fansipan – Bản làng vùng cao','Trải nghiệm cáp treo Fansipan khi thời tiết phù hợp. Buổi chiều tham quan bản làng, tìm hiểu đời sống địa phương.','Sáng, Trưa, Tối'),('290eb015-cfc8-4d5f-b1d1-7e20bba3e673','2026-11-03 13:35:59.873','2026-11-03 13:35:59.873','0ea37c53-eed2-4582-9c74-a4c15476ce68',2,'Hang Múa – Trở về Hà Nội','Dùng bữa sáng, tham quan Hang Múa và ngắm cảnh theo sức khỏe, điều kiện thời tiết. Trả phòng, thưởng thức ẩm thực địa phương rồi trở về Hà Nội.','Sáng, Trưa'),('2a8b7329-3379-488a-a4d2-4d6b764cc919','2026-11-17 11:19:04.070','2026-11-17 11:19:04.070','eae6d0f9-7082-45a3-84ee-5d0282a362d9',4,'Tuy Hòa – Tiễn đoàn','Tự do mua sắm đặc sản, trả phòng và đưa đoàn ra sân bay.','Sáng, Trưa'),('2ebdb241-71b3-45ff-835b-fb8a6b4f0f19','2026-11-17 11:19:04.128','2026-11-17 11:19:04.128','ae2aece0-5df9-4e60-beab-d96cb4062c39',3,'Suối Moọc – Trở về','Tham quan suối Moọc, dùng bữa trưa, trả phòng và ra sân bay.','Sáng, Trưa'),('369e2eb5-18c5-472c-8c25-55b173316a38','2026-11-17 11:19:04.067','2026-11-17 11:19:04.067','eae6d0f9-7082-45a3-84ee-5d0282a362d9',2,'Kỳ Co – Eo Gió','Di chuyển đến Kỳ Co, tắm biển và tham quan Eo Gió. Nghỉ đêm tại Quy Nhơn.','Sáng, Trưa, Tối'),('3901dc02-3f09-469a-af6b-e9ff7d4061b9','2026-11-03 13:35:59.822','2026-11-03 13:35:59.822','4fdf289d-42e5-47f5-9228-00417e3ccdf5',3,'Chợ địa phương – Tạm biệt Phú Quốc','Tự do mua sắm đặc sản, trả phòng và đưa đoàn ra sân bay.','Sáng, Trưa'),('3cf19c51-fe5f-42b3-8179-c0737d09b6e2','2026-11-17 11:19:04.055','2026-11-17 11:19:04.055','53acc064-c496-4164-a7b0-daef677bce4a',1,'Hà Nội – Huế – Sông Hương','Đón đoàn tại sân bay Huế, nhận phòng. Buổi tối đi thuyền trên sông Hương, nghe ca Huế.','Trưa, Tối'),('474e6eb6-fc46-431f-a9c1-29c9f0026f41','2026-11-17 11:19:04.115','2026-11-17 11:19:04.115','e37eabe6-5910-4e2d-a88e-f95883b57a80',2,'Biển Đầm Trầu – Hòn Bảy Cạnh','Tắm biển, tham quan các điểm thiên nhiên theo điều kiện thời tiết và thư giãn buổi tối.','Sáng, Trưa, Tối'),('481fafd1-95be-42d3-a721-491898e68eaa','2026-11-17 11:19:04.083','2026-11-17 11:19:04.083','814fed76-a590-4146-a634-bb26e353caf3',2,'Chợ nổi Cái Răng – Trở về','Đi thuyền tham quan chợ nổi Cái Răng vào buổi sáng sớm, dùng bữa sáng rồi trả phòng và trở về TP. Hồ Chí Minh.','Sáng, Trưa'),('492d0de0-c330-41e4-a650-6235e7f30b58','2026-11-03 13:35:59.841','2026-11-03 13:35:59.841','8d3308ac-3767-4355-9b9f-24ca5267bd52',3,'Lưu giữ kỷ niệm – Trở về','Mua sắm đặc sản địa phương, trả phòng và kết thúc chuyến đi.','Sáng, Trưa'),('523918ae-1993-4e5a-a9dc-8ead34c0abaa','2026-11-03 13:35:59.805','2026-11-03 13:35:59.805','a9f34825-b730-402b-8347-462cbc4753e0',3,'Ngũ Hành Sơn – Phố cổ Hội An','Tham quan Ngũ Hành Sơn. Buổi chiều dạo phố cổ Hội An, thưởng thức đặc sản địa phương và ngắm đèn lồng.','Sáng, Trưa, Tối'),('548df22a-9c8f-4cbb-b93a-e7c2bf661f16','2026-11-03 13:35:59.804','2026-11-03 13:35:59.804','a9f34825-b730-402b-8347-462cbc4753e0',2,'Bà Nà – Cầu Vàng','Tham quan Bà Nà Hills, chụp ảnh Cầu Vàng và khám phá các khu vui chơi theo lịch trình của đoàn.','Sáng, Trưa, Tối'),('595fc788-a6de-44e1-b378-ad70da2efa77','2026-11-17 11:19:04.056','2026-11-17 11:19:04.056','53acc064-c496-4164-a7b0-daef677bce4a',3,'Chợ Đông Ba – Trở về','Mua sắm đặc sản tại chợ Đông Ba, trả phòng và di chuyển ra sân bay.','Sáng, Trưa'),('5f8ddf01-0a24-4341-bcb2-259149b73dca','2026-11-17 11:19:04.082','2026-11-17 11:19:04.082','814fed76-a590-4146-a634-bb26e353caf3',1,'TP. Hồ Chí Minh – Cần Thơ','Đón đoàn, di chuyển đến Cần Thơ. Tham quan vườn trái cây, dùng bữa trưa đặc sản. Buổi tối dạo bến Ninh Kiều.','Trưa, Tối'),('63857a06-0560-4179-a33e-548e41e145e6','2026-11-03 13:35:59.840','2026-11-03 13:35:59.840','8d3308ac-3767-4355-9b9f-24ca5267bd52',1,'Thành phố ngàn hoa','Đón đoàn, di chuyển đến Đà Lạt và nhận phòng. Dạo hồ Xuân Hương và khám phá chợ đêm.','Trưa, Tối'),('79bb42e2-45fc-43f6-8bc6-5056ff9f2e19','2026-11-03 13:35:59.871','2026-11-03 13:35:59.871','0ea37c53-eed2-4582-9c74-a4c15476ce68',1,'Hà Nội – Hoa Lư – Tràng An','Đón đoàn tại Hà Nội, di chuyển đến Ninh Bình. Tham quan cố đô Hoa Lư, dùng bữa trưa và trải nghiệm thuyền tham quan Tràng An. Nhận phòng và nghỉ ngơi.','Trưa, Tối'),('7e0555a9-bf08-4ca8-b361-a6f8ea2ddd3d','2026-11-17 11:19:04.093','2026-11-17 11:19:04.093','e614d2b5-ce70-4ea7-9b93-e26b87f15c83',2,'Thác Dải Yếm – Trở về','Tham quan thác Dải Yếm, mua đặc sản địa phương, trả phòng và trở về Hà Nội.','Sáng, Trưa'),('8142effb-6de7-41cb-916e-d33df3780384','2026-11-03 13:35:59.820','2026-11-03 13:35:59.820','4fdf289d-42e5-47f5-9228-00417e3ccdf5',1,'Xin chào đảo ngọc','Đón đoàn tại sân bay Phú Quốc, nhận phòng khách sạn và thư giãn bên bờ biển.','Trưa, Tối'),('84ec4ede-d1e3-4d93-a0d0-c03d74563630','2026-11-03 13:35:59.832','2026-11-03 13:35:59.832','eb9b1c60-dac3-41dc-9a89-8bc28bfa818d',3,'Sa Pa – Hà Nội','Tự do dạo chợ, thưởng thức ẩm thực vùng cao và trở về Hà Nội.','Sáng, Trưa'),('882d577e-297a-4ffc-a7ff-d79421251784','2026-11-17 11:19:04.092','2026-11-17 11:19:04.092','e614d2b5-ce70-4ea7-9b93-e26b87f15c83',1,'Hà Nội – Mộc Châu','Đón đoàn tại Hà Nội, di chuyển đến Mộc Châu. Tham quan đồi chè trái tim và các điểm check-in theo mùa. Nhận phòng nghỉ đêm.','Trưa, Tối'),('954351ed-183c-4e13-8c9e-b01248c6484d','2026-11-17 11:19:04.102','2026-11-17 11:19:04.102','8b0b6e6b-6ed9-43e7-91f2-637233dde14d',1,'Hà Nội – Hà Giang','Đón đoàn tại Hà Nội, di chuyển đến thành phố Hà Giang, nhận phòng và nghỉ ngơi.','Trưa, Tối'),('9582b359-89cc-4d5e-91e0-938c1a479324','2026-11-17 11:19:04.126','2026-11-17 11:19:04.126','ae2aece0-5df9-4e60-beab-d96cb4062c39',1,'Hà Nội – Đồng Hới – Phong Nha','Đón đoàn tại sân bay Đồng Hới, di chuyển đến Phong Nha, nhận phòng và dạo quanh thị trấn.','Trưa, Tối'),('b4ee7139-1992-414b-9ea3-1c17f713f729','2026-11-17 11:19:04.066','2026-11-17 11:19:04.066','eae6d0f9-7082-45a3-84ee-5d0282a362d9',1,'Đến Quy Nhơn','Đón đoàn tại sân bay Phù Cát, về thành phố nhận phòng. Dạo biển và thưởng thức bún chả cá.','Trưa, Tối'),('bb28d0c2-fcd3-4e20-bf43-0f24b10cd182','2026-11-17 11:19:04.103','2026-11-17 11:19:04.103','8b0b6e6b-6ed9-43e7-91f2-637233dde14d',2,'Quản Bạ – Yên Minh – Đồng Văn','Qua Cổng Trời Quản Bạ, rừng thông Yên Minh và đến cao nguyên đá Đồng Văn. Nghỉ đêm tại Đồng Văn.','Sáng, Trưa, Tối'),('bd8073d9-bd0a-43a5-87e7-c06bac9a47db','2026-11-17 11:19:04.115','2026-11-17 11:19:04.115','e37eabe6-5910-4e2d-a88e-f95883b57a80',1,'TP. Hồ Chí Minh – Côn Đảo','Đón đoàn tại sân bay Côn Đảo, nhận phòng. Buổi chiều tham quan các di tích lịch sử trên đảo.','Trưa, Tối'),('cf8dfe02-5f0b-4b2b-8f10-15221bdc46b2','2026-11-03 13:35:59.806','2026-11-03 13:35:59.806','a9f34825-b730-402b-8347-462cbc4753e0',4,'Chợ Hàn – Tiễn đoàn','Mua sắm đặc sản tại chợ Hàn, trả phòng và di chuyển ra sân bay.','Sáng, Trưa'),('dbea563d-063d-4d31-b577-8ffdcd177c78','2026-11-17 11:19:04.055','2026-11-17 11:19:04.055','53acc064-c496-4164-a7b0-daef677bce4a',2,'Đại Nội – Lăng tẩm','Tham quan Đại Nội Huế, chùa Thiên Mụ và một số lăng tẩm triều Nguyễn theo lịch trình của đoàn.','Sáng, Trưa, Tối'),('e0dbd474-1743-429c-a64c-faa5b1664106','2026-11-03 13:35:59.849','2026-11-03 13:35:59.849','52a95074-8a23-4618-860a-0e91ea84726f',1,'Hà Nội – Hạ Long – Du thuyền','Đón đoàn tại điểm hẹn ở Hà Nội, di chuyển đến Hạ Long và lên du thuyền. Dùng bữa trưa, ngắm cảnh vịnh và tham gia hoạt động ngoài trời tùy điều kiện thời tiết. Nghỉ đêm trên du thuyền.','Trưa, Tối'),('e3eaa2d5-3fd7-4973-a199-6ad77843c590','2026-11-03 13:35:59.841','2026-11-03 13:35:59.841','8d3308ac-3767-4355-9b9f-24ca5267bd52',2,'Cao nguyên xanh – Không gian cà phê','Tham quan các điểm ngắm cảnh và vườn hoa, tìm hiểu văn hóa cà phê cao nguyên.','Sáng, Trưa, Tối'),('e57a9c1e-cff3-4a79-8971-e1e18112bf31','2026-11-17 11:19:04.068','2026-11-17 11:19:04.068','eae6d0f9-7082-45a3-84ee-5d0282a362d9',3,'Gành Đá Đĩa – Phú Yên','Tham quan Gành Đá Đĩa, Mũi Điện theo điều kiện thời tiết. Nhận phòng tại Tuy Hòa.','Sáng, Trưa, Tối'),('e82c8b9b-f2ad-4ee8-aba1-2ff163fa7d13','2026-11-17 11:19:04.139','2026-11-17 11:19:04.139','80f2277c-3ac2-402b-b575-67e73a0a3165',2,'Đồi cát – Trở về','Ngắm bình minh trên đồi cát, dùng bữa sáng, trả phòng và trở về TP. Hồ Chí Minh.','Sáng, Trưa'),('e870fdd8-c7fb-471b-bcad-b814d2be4348','2026-11-03 13:35:59.803','2026-11-03 13:35:59.803','a9f34825-b730-402b-8347-462cbc4753e0',1,'Đà Nẵng – Biển Mỹ Khê','Đón đoàn tại sân bay Đà Nẵng, dùng bữa trưa và nhận phòng. Buổi chiều tự do khám phá biển Mỹ Khê.','Trưa, Tối'),('f033220a-522a-4afe-bd2b-d273ffc5c15a','2026-11-17 11:19:04.116','2026-11-17 11:19:04.116','e37eabe6-5910-4e2d-a88e-f95883b57a80',3,'Chợ Côn Đảo – Trở về','Mua đặc sản, trả phòng và ra sân bay.','Sáng, Trưa'),('f5547a81-0c2f-4be1-97cb-da9adc75c0df','2026-11-17 11:19:04.105','2026-11-17 11:19:04.105','8b0b6e6b-6ed9-43e7-91f2-637233dde14d',4,'Hà Giang – Hà Nội','Dùng bữa sáng, trả phòng và di chuyển về Hà Nội.','Sáng, Trưa'),('f89b06dd-de93-40d9-a0d5-12b25f1457f2','2026-11-17 11:19:04.020','2026-11-17 11:19:04.020','2cd9d21e-26f1-42d4-8a7d-1df5d2bf517a',1,'TP. Hồ Chí Minh – Nha Trang','Đón đoàn tại điểm hẹn, di chuyển đến Nha Trang. Nhận phòng, buổi chiều tự do tắm biển và dạo phố biển.','Trưa, Tối'),('f9a9c923-489b-4a1f-b785-4964e748c91b','2026-11-03 13:35:59.830','2026-11-03 13:35:59.830','eb9b1c60-dac3-41dc-9a89-8bc28bfa818d',1,'Hà Nội – Sa Pa','Đón đoàn tại điểm hẹn ở Hà Nội, di chuyển đến Sa Pa. Nhận phòng và khám phá thị trấn.','Trưa, Tối'),('fa071c4b-3bc4-46d1-a0b8-c09aa0470561','2026-11-17 11:19:04.138','2026-11-17 11:19:04.138','80f2277c-3ac2-402b-b575-67e73a0a3165',1,'TP. Hồ Chí Minh – Mũi Né','Đón đoàn, di chuyển đến Mũi Né. Tham quan suối Tiên, làng chài và nhận phòng. Buổi tối thưởng thức hải sản.','Trưa, Tối'),('fc96cab8-0674-469a-af6d-750eddc4949c','2026-11-03 13:35:59.851','2026-11-03 13:35:59.851','52a95074-8a23-4618-860a-0e91ea84726f',2,'Bình minh trên vịnh – Hà Nội','Đón bình minh, dùng bữa sáng và tiếp tục ngắm cảnh vịnh theo tuyến của du thuyền. Trả phòng, lên bờ và di chuyển về Hà Nội.','Sáng, Trưa'),('fedc4f67-d0d6-4877-9075-7d35353fe245','2026-11-17 11:19:04.029','2026-11-17 11:19:04.029','2cd9d21e-26f1-42d4-8a7d-1df5d2bf517a',2,'Tour đảo – Vịnh Nha Trang','Đi tàu tham quan các đảo trong vịnh, tắm biển và tham gia hoạt động ngoài trời tùy điều kiện thời tiết. Buổi tối tự do.','Sáng, Trưa, Tối');
